using System.Text.Json;
namespace LadderRecords;
[System.Runtime.Versioning.SupportedOSPlatform("windows10.0.19041")]
static class DetectionChecks
{
 public static void Run(Catalog catalog){var notes=new List<string>();void Check(bool condition,string message){if(!condition)throw new Exception(message);notes.Add("PASS: "+message);}
  var chart=new SteamChart("FREESTYLE","Fundamental",8,"SC");var songs=SteamSongs.Find(catalog,chart);Check(songs.Count==1,"Unique Steam title lookup");Check(SteamSongs.Find(catalog,chart with{Name="Burn it Down",Button=4}).Count==2,"Case-only duplicate titles require audio");Check(SteamSongs.Find(catalog,chart with{Name="脳天直撃",Button=4}).Count==1,"Japanese title lookup without OCR");Check(SteamSongs.Find(catalog,chart with{Name="missing song"}).Count==0,"Unknown title is not guessed");
  var gate=new JudgeGate();Check(gate.Observe("노말",0)==null,"Judge does not lock immediately");Check(gate.Observe("노말",.99)==null,"Judge does not lock before one second");Check(gate.Observe("노말",1)=="노말","Judge locks after one observed second");gate.Reset();gate.Observe("노말",0);gate.Observe(null,.5);Check(gate.Observe("노말",1)==null&&gate.Observe("노말",1.99)==null,"Uncertain frame breaks absence timer");Check(gate.Observe("노말",2)=="노말","Validated absence must restart full interval");gate.Reset();gate.Observe("하드",0);Check(gate.Observe("맥스",.5)==null&&gate.Observe("맥스",1.49)==null&&gate.Observe("맥스",1.5)=="맥스","Changed judge restarts interval");gate.Reset();gate.Observe("노말",0);Check(gate.Observe("노말",4)==null,"Long capture gap cannot confirm normal");

  var selection=new Selection(songs[0].Id,8,"SC","하드",0);var session=new Session();session.Detect(selection);Check(session.Locked==selection,"Song selection accepts resolved Steam identity immediately");session.Current=98.76m;var pending=session.Begin("test");session.Detect(selection with{Button=6});Check(session.Pending==pending&&session.Locked==selection,"Pending snapshot and selection remain immutable");session.Cancel();session.Next();Check(session.Locked==null&&session.Current==null,"Rescan clears runtime selection");
  Check(Recognizer.ParseRate("100.00%") is 100m&&Recognizer.ParseRate("98.76 %") is 98.76m&&Recognizer.ParseRate("101.00%") is null&&Recognizer.ParseRate("9876%") is null,"HUD RATE parser preserves two decimals and range");File.WriteAllLines(Path.Combine(AppContext.BaseDirectory,"detection-validation.txt"),notes);
 }
 public static void Audio(string root){var manifest=JsonSerializer.Deserialize<JsonElement>(File.ReadAllText(Path.Combine(root,"video-manifest.json")));var entries=manifest.EnumerateArray().ToArray();var rows=new List<object>();
  for(int i=0;i<entries.Length;i+=2){var pair=entries.Skip(i).Take(2).ToArray();var references=pair.ToDictionary(p=>p.GetProperty("id").GetString()!,p=>AudioIdentity.Load(Path.Combine(AppContext.BaseDirectory,"data","audio",p.GetProperty("id").GetString()!.Split(':')[1]+".bin")));
   foreach(var entry in pair){string id=entry.GetProperty("id").GetString()!,video=entry.GetProperty("query").GetString()!;bool accepted=false;for(int end=8;end<=10;end++){string path=Path.Combine(root,"opening-clips",$"{video}-{end-8:00}-{end:00}.wav");var watch=System.Diagnostics.Stopwatch.StartNew();var decision=AudioIdentity.Decide(AudioIdentity.Features(AudioIdentity.ReadWav(path)),references);rows.Add(new{song=id,end,decision,ms=watch.Elapsed.TotalMilliseconds});if(decision.SongId!=null){if(decision.SongId!=id)throw new Exception("Wrong audio identity: "+id);accepted=true;break;}}if(!accepted)throw new Exception("Opening audio not accepted by 10 seconds: "+id);}
  }File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"audio-validation.json"),JsonSerializer.Serialize(rows,new JsonSerializerOptions{WriteIndented=true}));
 }
 public static async Task Screen(Catalog catalog,string file,int gear,string mode){using var raw=new Bitmap(file);using var frame=new Bitmap(1920,1080);using(var g=Graphics.FromImage(frame))g.DrawImage(raw,0,0,1920,1080);using var reader=new Recognizer(catalog);var watch=System.Diagnostics.Stopwatch.StartNew();var result=await reader.Read(frame,mode,gear);File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"screen-validation.json"),JsonSerializer.Serialize(new{result,ms=watch.Elapsed.TotalMilliseconds}));}
 public static async Task Fixtures(Catalog catalog){var rows=new List<string>();using var font=new Font("Arial",12,FontStyle.Bold,GraphicsUnit.Pixel);using var widgetFont=new Font("Arial",18,FontStyle.Bold,GraphicsUnit.Pixel);
  for(int gear=0;gear<3;gear++){using var reader=new Recognizer(catalog);int center=gear==1?1600:gear==2?960:320;
   foreach(int y in new[]{30,320,640,1020}){using var frame=new Bitmap(1920,1080);using(var g=Graphics.FromImage(frame)){g.Clear(Color.Black);g.DrawString("RATE",font,Brushes.White,center-50,y);g.DrawString("98.54%",font,Brushes.White,center+8,y);}var rate=await reader.ReadRate(frame,gear);if(rate!=98.54m)throw new Exception($"HUD movement fixture: gear={gear}, y={y}, read={rate}");rows.Add($"PASS HUD gear={gear}, y={y}, value={rate}");}
   foreach(bool red in new[]{false,true})foreach(bool hard in new[]{false,true}){using var frame=new Bitmap(1920,1080);int x=gear==1?20:1660;using(var g=Graphics.FromImage(frame)){g.Clear(Color.Black);if(red)g.FillRectangle(Brushes.Red,gear==2?80:740,100,440,60);g.DrawString("LADDER MATCH",widgetFont,Brushes.White,x,290);g.DrawString("SEARCHING...",widgetFont,Brushes.White,x,320);g.DrawString("RECORD SAVE OFF",font,Brushes.White,x,350);if(hard){g.FillRectangle(Brushes.Crimson,x,405,230,28);g.DrawString("HARD JUDGEMENT",font,Brushes.White,x+5,408);}}var judge=await reader.ReadJudge(frame,"LADDERMATCH",gear);if(judge!=(hard?"하드":"노말"))throw new Exception($"Practice fixture gear={gear},hard={hard},read={judge}, detail={reader.Detail}");rows.Add($"PASS practice gear={gear}, hard={hard}, red={red}");}
  }
  using var blank=new Bitmap(1920,1080);using var guard=new Recognizer(catalog);var missing=await guard.Read(blank,"LADDERMATCH",0);if(missing.Judge!=null||missing.Rate!=null)throw new Exception("Blank ladder frame confirmed normal");var open=await guard.Read(blank,"OPENMATCH",0);if(open.Judge!=null)throw new Exception("Blank openmatch frame confirmed normal");rows.Add("PASS blank/occluded frames cannot confirm normal");File.WriteAllLines(Path.Combine(AppContext.BaseDirectory,"screen-fixtures-validation.txt"),rows);
 }
}
